var i=`1100-or-lam`;var n=`world-1100`;var s=`LA`;var t=`southeast-asia`;var r=4;var o=108;var g={en:`Or Lam`,ua:`Ор лам`};var l={en:`Or Lam is a dish from Laos prepared with beef chuck, lemongrass, galangal, eggplant. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Ор лам, страва кухні країни Лаос, яку готують із таких продуктів: яловича лопатка, лемонграс, галангал, баклажан. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var d=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 12 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 12 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:12,i:[[`beef-chuck`,730,`g`],[`canola-oil`,35,`ml`]]},{en:`Add the braising liquid and seasonings, cover and cook gently for about 75 minutes until the meat is tender and safely cooked.`,ua:`Додайте рідину та приправи для тушкування, накрийте кришкою й готуйте на малому вогні приблизно 75 хвилин до м’якості та повної готовності м’яса.`,t:[`braising`],m:75,i:[[`water`,820,`ml`],[`lemongrass`,3,`pcs`],[`galangal`,40,`g`],[`eggplant`,260,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 18 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 18 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:18,i:[[`shiitake-mushroom`,180,`g`],[`cilantro`,20,`g`],[`thai-basil`,20,`g`]]},{en:`Stir in these seasonings and additions. Taste, adjust the balance and let the dish stand briefly before serving.`,ua:`Додайте приправи та завершальні складники. Спробуйте, збалансуйте смак і дайте страві трохи настоятися перед подаванням.`,t:[`seasoning`,`finishing-with-herbs`],m:3,i:[[`fish-sauce`,30,`ml`],[`crushed-red-pepper`,5,`g`]]}];var h={slug:i,id:n,country:`LA`,region:t,servings:4,minutes:108,title:g,text:l,steps:d};export{s as country,h as default,n as id,o as minutes,t as region,r as servings,i as slug,d as steps,l as text,g as title};